211	
212	    /**
213	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
214	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
215	     * Validation already rejects {@code null} values and the pattern-constrained fields
216	     * when blank, but {@code address} and {@code city} have no pattern, so a
217	     * whitespace-only value would otherwise slip through.
218	     *
219	     * @param ownerFieldsDto the submitted owner fields
220	     * @throws RequiredFieldsMissingException if any required field is missing or blank
221	     */
222	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
223	        List<String> errors = new ArrayList<>();
224	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
225	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
226	        requireText("address", ownerFieldsDto.getAddress(), errors);
227	        requireText("city", ownerFieldsDto.getCity(), errors);
228	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
229	        if (!errors.isEmpty()) {
230	            throw new RequiredFieldsMissingException(errors);
231	        }
232	    }
233	
234	    private static void requireText(String field, String value, List<String> errors) {
235	        if (value == null || value.isBlank()) {
236	            errors.add(field);
237	        }
238	    }
239	
240	    /**
241	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
242	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
243	     * and echoed back in that form.
244	     *
245	     * @param ownerFieldsDto the submitted owner fields
246	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
247	     *                                        valid E.164 number
248	     */
249	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
250	        String e164 = toE164(ownerFieldsDto.getTelephone());
251	        if (e164 == null) {
252	            throw new RequiredFieldsMissingException(List.of("telephone"));
253	        }
254	        ownerFieldsDto.setTelephone(e164);
255	    }
256	
257	    /**
258	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
259	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
260	     * and country code are present they are kept; otherwise country code {@code '+61'} is
261	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
262	     * must contain 8 to 15 digits after the {@code '+'}.
263	     *
264	     * @param raw the submitted telephone, possibly {@code null}
265	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
266	     */
267	    private static String toE164(String raw) {
268	        if (raw == null) {
269	            return null;
270	        }
271	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
272	        String digits;
273	        if (cleaned.startsWith("+")) {
274	            digits = cleaned.substring(1);
275	        } else {
276	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
277	            digits = "61" + national;
278	        }
279	        if (!digits.matches("[0-9]{8,15}")) {
280	            return null;
281	        }
282	        return "+" + digits;
283	    }
284	
285	    /**
286	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
287	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
288	     * each stored owner's telephone is normalized the same way before comparison so differing
289	     * input formats collapse to the same value.
290	     *
291	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
292	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
293	     *                                     same E.164 telephone
294	     */
295	    /**
296	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
297	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
298	     * the parts may contain whitespace or a second {@code @}.
299	     */
300	    private static final Pattern EMAIL_PATTERN =
301	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
302	
303	    /**
304	     * Normalizes the submitted email when present: the value is trimmed, required to be a
305	     * syntactically valid address, and written back lower-cased so it is persisted and echoed
306	     * back in canonical form. A {@code null} email is left untouched — the field is optional.
307	     *
308	     * @param ownerFieldsDto the submitted owner fields
309	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically valid
310	     */
311	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
312	        String email = ownerFieldsDto.getEmail();
313	        if (email == null) {
