325	     * {@code registrationDate}, it is set to the server's current date so it is persisted
326	     * and echoed back in ISO 'YYYY-MM-DD' format. A supplied value is left untouched.
327	     *
328	     * @param ownerFieldsDto the submitted owner fields
329	     */
330	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
