346	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
347	        int sequence = this.clinicService.findAllOwners().size() + 1;
348	        owner.setCustomerCode(String.format("%s-%04d", last3, sequence));
349	    }
