353	     * formatted {@code 'HH-<HEX12>'} where HEX12 is the first 12 upper-cased hex characters of the
354	     * SHA-256 digest of the owner's collapsed {@code lastName} and {@code address} (see
355	     * {@link #collapse}) joined by a {@code '\n'}. Because it is derived purely from those two
356	     * canonicalized fields, every owner in the same household — including one joining an existing
357	     * household via {@code sharesHousehold} — is assigned the same value, independent of create
358	     * order.
359	     *
360	     * @param owner the owner being created (with its {@code lastName} and {@code address} already set)
361	     */
362	    private void assignHouseholdId(Owner owner) {
363	        String key = collapse(owner.getLastName()) + "\n" + collapse(owner.getAddress());
364	        owner.setHouseholdId("HH-" + sha256Hex(key).substring(0, 12).toUpperCase(Locale.ROOT));
365	    }
