369	     *
370	     * @param value the string to hash
371	     * @return the 64-character lower-case hex digest
372	     */
373	    private static String sha256Hex(String value) {
374	        try {
375	            byte[] digest = MessageDigest.getInstance("SHA-256")
376	                .digest(value.getBytes(StandardCharsets.UTF_8));
377	            StringBuilder sb = new StringBuilder(digest.length * 2);
378	            for (byte b : digest) {
379	                sb.append(String.format("%02x", b));
380	            }
